B.ah6=new A.pS("A\xe7\u0131kken uygulama her a\xe7\u0131l\u0131\u015fta parmak izi / y\xfcz tan\u0131ma ister. Biyometrik verilerin cihaz\u0131ndan asla \xe7\u0131kmaz ve uygulama taraf\u0131ndan kaydedilmez; do\u011frulama ba\u015far\u0131s\u0131z olursa \u015fifreyle giri\u015f her zaman m\xfcmk\xfcnd\xfcr.",null)
B.ah7=new A.pS("Onayland\u0131\u011f\u0131nda di\u011fer cihazlardaki oturumlar\u0131n g\xfcvenlik i\xe7in kapat\u0131l\u0131r.",null)
B.ah8=new A.pS("Hen\xfcz kay\u0131tl\u0131 olay yok.",null)
B.ah9=new A.pS("Bu cihazda \u015fu an kullan\u0131labilir biyometri yok (kay\u0131tl\u0131 parmak izi/y\xfcz silinmi\u015f ya da sens\xf6r kullan\u0131lam\u0131yor olabilir). Kilit a\xe7\u0131k oldu\u011fu i\xe7in a\xe7\u0131l\u0131\u015fta do\u011frulama istenmeye devam eder; kapatmak istersen a\u015fa\u011f\u0131daki anahtar\u0131 kullan \u2014 de\u011fi\u015fiklik cihaz ekran kilidinle (PIN/desen) do\u011frulan\u0131r.",null)
B.aha=new A.pS("\u015e\xfcpheli bir durum fark edersen bu cihaz d\u0131\u015f\u0131ndaki t\xfcm oturumlar\u0131 tek dokunu\u015fla kapatabilirsin.",null)
B.ah1=new A.pO("Kesin sonu\xe7 veya kazan\xe7 vaadi de\u011fildir.",null)
B.ah3=new A.pO("Yaln\u0131z resm\xee 90 dakika sonucu kesindir; canl\u0131 ve ge\xe7ici veriler kesin say\u0131lmaz.",null)
B.agZ=new A.pO('Analizler, oynanma y\xfczdeleri ve oran hareketleri yaln\u0131zca karar deste\u011fidir; kesin sonu\xe7 de\u011fildir. Veri eksikse "veri yok" yaz\u0131l\u0131r, tahmin uydurulmaz.',null)
B.Sf=s([B.ah1,B.ah3,B.agZ],t.p)
B.ahc=new A.ya("Analiz d\xfcr\xfcstl\xfc\u011f\xfc",B.Sf,null)
B.ah_=new A.pO(u.y,null)
